// client/src/pages/CouponCenter.jsx (최종 수정 완료)

import React, { useEffect, useState } from 'react';
// 1. 쿠폰 관련 함수는 couponApi에서 가져옵니다.
import { getMyCoupons, redeemCoupon } from '../api/couponApi'; 
// 2. 🚨 룰렛 관련 함수는 rouletteApi에서 가져옵니다.
import { getRouletteRewards, spinRoulette } from '../api/rouletteApi'; 
import RouletteWheel from '../components/RouletteWheel'; 

function CouponCenter() {
  const [coupons, setCoupons] = useState([]);
  // 룰렛 상태
  const [rewards, setRewards] = useState([]); 
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotationAngle, setRotationAngle] = useState(0); 
  const [spinResult, setSpinResult] = useState(null); 
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        
        // 1. 내 쿠폰 목록 로드
        const couponRes = await getMyCoupons();
        setCoupons(couponRes.data || []); 
        
        // 2. 🚨 룰렛 보상 목록 로드 (수정된 부분)
        const rewardsRes = await getRouletteRewards(); 
        
        // 🏆 최종 수정: rewardsRes가 배열이 아니면 (예: { rewards: [...] } 형태라면) 
        // rewardsRes.rewards를 사용하여 안전하게 배열을 추출하도록 변경.
        setRewards(Array.isArray(rewardsRes) ? rewardsRes : rewardsRes.rewards || []);
        
      } catch (err) {
        console.error('load data failed', err);
        alert('데이터 로드에 실패했습니다.');
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);
  
  // 룰렛 스핀 로직
  const handleSpin = async () => {
    if (isSpinning || rewards.length === 0) return;
    setIsSpinning(true);
    setSpinResult(null);

    try {
        // 서버에서 스핀 결과를 받고, 최종 멈출 각도를 계산합니다.
        const res = await spinRoulette(); 
        const resultReward = res.reward; 
        setSpinResult(res); 
        
        // 룰렛 멈출 각도 계산 로직
        const totalSegments = rewards.length;
        const segmentAngle = 360 / totalSegments;
        const rewardIndex = rewards.findIndex(r => r.name === resultReward.name); 
        
        if (rewardIndex === -1) throw new Error("유효하지 않은 보상입니다. 룰렛 데이터를 확인하세요.");

        const stopAngle = 1800 + (totalSegments - rewardIndex) * segmentAngle - (segmentAngle / 2);
        
        setRotationAngle(prev => prev + stopAngle);

        setTimeout(() => {
             setIsSpinning(false);
             alert(`🎉 축하합니다! ${resultReward.name}에 당첨되었습니다!`);
        }, 4000); 

    } catch(err) {
        alert('룰렛 스핀에 실패했습니다: ' + (err.response?.data?.message || err.message));
        setIsSpinning(false);
    }
  };

  const handleCopy = (code) => {
    navigator.clipboard.writeText(code);
    alert('쿠폰 코드가 복사되었습니다.');
  };

  const handleRedeem = async (id) => {
    try {
      const res = await redeemCoupon(id);
      alert('쿠폰 사용 완료!');
      
      setCoupons(prevCoupons => 
        prevCoupons.map(c => (c._id === id ? res.data : c)) 
      );
    } catch (err) {
      alert('사용 실패: ' + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div style={{ padding: 20 }}>
      {/* 룰렛 섹션 */}
      <section style={{ marginBottom: 40, borderBottom: '1px solid #eee', paddingBottom: 20 }}>
        <h2>룰렛 게임 참여</h2>
        
        {loading ? (
          <p>데이터 로드 중...</p>
        ) : rewards.length > 0 ? (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', marginTop: 20 }}>
            <RouletteWheel 
              rewards={rewards} 
              isSpinning={isSpinning} 
              spinResult={spinResult} 
              rotationAngle={rotationAngle} 
            />
            <button 
                onClick={handleSpin} 
                disabled={isSpinning} 
                style={{ marginTop: 20, padding: '12px 24px', fontSize: 18, background: isSpinning ? '#ccc' : '#4CAF50', color: '#fff', border: 'none', borderRadius: 8 }}
            >
                {isSpinning ? '돌아가는 중...' : '룰렛 돌리기!'}
            </button>
            {spinResult && <p style={{ marginTop: 10, fontWeight: 700 }}>당첨: {spinResult.reward.name}</p>}
          </div>
        ) : (
          <p>룰렛 보상 데이터를 로드할 수 없거나, 서버에 보상 설정이 없습니다.</p>
        )}
      </section>

      <h2>내 쿠폰</h2>

      {coupons.length === 0 && <p>아직 쿠폰이 없습니다.</p>}

      {coupons.map(coupon => (
        <div key={coupon._id} style={{ padding: 12, border: '1px solid #ddd', marginBottom: 8, borderRadius: 8 }}>
          <div>
            <strong>{coupon.brand}</strong> — {coupon.discount}% 할인
          </div>
          <div style={{ marginTop: 6 }}>코드: <strong>{coupon.code}</strong></div>

          {coupon.externalUrl && (
            <button
              style={{ marginTop: 6 }}
              onClick={() => {
                handleCopy(coupon.code); 
                window.open(coupon.externalUrl, '_blank');
              }}
            >
              사용처 이동 (코드 자동 복사)
            </button>
          )}

          {!coupon.redeemed && (
            <button style={{ marginLeft: 8 }} onClick={() => handleRedeem(coupon._id)}>
              쿠폰 사용 처리
            </button>
          )}

          {coupon.redeemed && <span style={{ marginLeft: 8, color: 'green' }}>✓ 사용 완료</span>}
        </div>
      ))}
    </div>
  );
}

export default CouponCenter;
